 | items = {{icon|g}}{{icon|m}}{{icon|t}} Choice of: [[Strong Iron Sword of Fire]], [[Strong Iron Sword of Water]] or [[Strong Iron Sword of Earth]]<br>{{icon|re}}{{icon|w}}{{icon|r}}{{icon|n}} Choice of: [[Strong Iron Axe of Fire]], [[Strong Iron Axe of Water]], or [[Strong Iron Axe of Earth]]<br>{{icon|en}} Choice of: [[Strong Iron Rifle of Earth]], [[Strong Iron Rifle of Fire]], or [[Strong Iron Rifle of Water]]<br>{{icon|e}} Choice of: [[Strong Soft Wood Focus of Earth]], [[Strong Soft Wood Focus of Fire]], or [[Strong Soft Wood Focus of Water]]
 | unlocks = {{icon|any}} [[Elite skill|Elite Skill]]s {{#info:You've unlocked your elite-skill slot. Spend hero points to acquire one of your most effective profession-based skills.}}<br>{{icon|en}} Profession Skill 5{{#info:You've unlocked your fifth profession skill. F5 now activates a different skill based on the ability in your elite-skill slot.}}
}}

