 | items = {{icon|g}}{{icon|re}}{{icon|w}} Choice of: [[Strong Reinforced Scale Gauntlets of Lyssa]], [[Strong Reinforced Scale Gauntlets of Melandru]], or [[Strong Reinforced Scale Gauntlets of Grenth]]<br>{{icon|en}}{{icon|r}}{{icon|t}} Choice of: [[Strong Privateer Gloves of Lyssa]], [[Strong Privateer Gloves of Melandru]], or [[Strong Privateer Gloves of Grenth]]<br>{{icon|e}}{{icon|m}}{{icon|n}} Choice of: [[Strong Cabalist Gloves of Lyssa (level 39 reward)|Strong Cabalist Gloves of Lyssa]], [[Strong Cabalist Gloves of Melandru]], or [[Strong Cabalist Gloves of Grenth]]
