 | level = 44
 | attributes = 24
 | items = {{item icon|Fine Salvage Kit}}
 | info = Fine [[Salvage]] Tools {{#info:You can now use Fine Salvage Kits. These kits have a 15% chance of finding rare materials and a 40% chance of recovering equipment upgrades.}}
}}

{{Level rewards
